const PATTERNS = {
  lv: [
    [/^(\d+(?:[.,]\d+)?) °C mean surface temperature$/, "$1 °C vidējā virsmas temperatūra"],
    [/^(\d+) annual summer surface temperature maps$/, "$1 ikgadējas vasaras virsmas temperatūras kartes"],
    [/^(\d+) annual exceptionally hot area maps$/, "$1 ikgadējas ārkārtīgi karsto teritoriju kartes"],
    [/^(\d+) observations (.+)$/, "$1 novērojumi $2"],
    [/^Average usable coverage: (.+) of the city\.$/, "Vidējais izmantojamais pārklājums: $1 no pilsētas."],
    [/^Best observation: (.+) of the city readable\.$/, "Labākais novērojums: nolasāmi $1 no pilsētas."],
    [/^The orthophoto basemap follows the next available full-city Riga orthophoto year from the municipal\/LGIA services\. Available years in the app are (.+); the advertised 2021 source is not used because it does not serve reliable WebMercator tiles, and the available 2025 service only covers the Central Market area\. Requests are constrained to the Riga map extent\.$/, (years) => `Ortofoto fons seko nākamajam pieejamajam pilnas pilsētas Rīgas ortofoto gadam no pašvaldības/LGIA pakalpojumiem. Lietotnē pieejamie gadi ir ${years}; publicētais 2021. gada avots netiek izmantots, jo tas nesniedz uzticamas WebMercator flīzes, un pieejamais 2025. gada pakalpojums aptver tikai Centrāltirgus teritoriju. Pieprasījumi ir ierobežoti Rīgas kartes tvērumā.`],
    [/^#(\d+) by (.+)$/, "#$1 pēc $2"],
    [/^(\d+) years$/, "$1 gadi"],
    [/^(\d+) year$/, "$1 gads"],
    [/^(\d+) anomalous years$/, "$1 anomāli gadi"],
    [/^(\d+) anomalous year$/, "$1 anomāls gads"],
    [/^0 anomalous years$/, "0 anomālu gadu"],
    [/^(\d+) chronic years$/, "$1 hroniski gadi"],
    [/^(\d+) chronic year$/, "$1 hronisks gads"],
    [/^0 chronic years$/, "0 hronisku gadu"],
    [/^(\d+) chronic, (\d+) anomalous$/, "$1 hroniski, $2 anomāli"],
    [/^(\d+) chronic years, (\d+) anomalous years\.$/, "$1 hroniski gadi, $2 anomāli gadi."],
    [/^Summer \*\*([^*]+)\*\* compared with the 2013-2026 historical average, with (.+)\.$/, (mood, exceptional) => `Vasara **${phrase("lv", mood)}** salīdzinājumā ar 2013-2026 vēsturisko vidējo, ar ${phrase("lv", exceptional)}.`],
    [/^Summer \*\*([^*]+)\*\*: the one with the highest mean surface temperature in the 2013-2026 series, with (.+)\.$/, (mood, exceptional) => `Vasara **${phrase("lv", mood)}**: ar augstāko vidējo virsmas temperatūru 2013-2026 sērijā, ar ${phrase("lv", exceptional)}.`],
    [/^One of the summers with the lowest mean surface temperature in the 2013-2026 series, with (.+)\.$/, (exceptional) => `Viena no vasarām ar zemāko vidējo virsmas temperatūru 2013-2026 sērijā, ar ${phrase("lv", exceptional)}.`],
    [/^This point is structurally hot compared with the city and shows (.+) compared with its own history\.$/, (signal) => `Šis punkts ir strukturāli karsts salīdzinājumā ar pilsētu un rāda ${phrase("lv", signal)} salīdzinājumā ar savu vēsturi.`],
    [/^This point shows (.+) compared with its own history, without being one of Riga's areas with the structurally highest surface temperature\.$/, (signal) => `Šis punkts rāda ${phrase("lv", signal)} salīdzinājumā ar savu vēsturi, bet nav viena no Rīgas teritorijām ar strukturāli augstāko virsmas temperatūru.`],
    [/^Summary of the summer satellite overpasses used to build the (\d{4}) map\.$/, "Vasaras satelītu pārlidojumu kopsavilkums, kas izmantoti $1. gada kartes izveidei."],
    [/^(\d+) 1 km cells intersecting Riga$/, "$1 šūnas (1 km), kas krustojas ar Rīgu"],
    [/^Showing (\d+)-(\d+) of (\d+) apkaimes$/, "Rāda $1-$2 no $3 apkaimēm"],
    [/^Page (\d+)$/, "$1. lapa"],
    [/^(\d+)-(\d+) years$/, "$1-$2 gadi"],
    [/^(\d+)-(\d+) chronic years$/, "$1-$2 hroniski gadi"],
    [/^(\d+)-(\d+) anomalous years$/, "$1-$2 anomāli gadi"],
    [/^(surface|vegetation|day-night range|reflectance): (absorbing|medium|reflective|sparse|moderate|dense|lower|wider|-?\d+(?:\.\d+)?)$/, (title, value) => `${TRANSLATIONS.lv[title] || title}: ${TRANSLATIONS.lv[value] || value}`],
    [/^n\/a\s?(%|°C)$/, "nav datu"],
  ],
};

function phrase(language, value) {
  return PHRASES[language]?.[value] || value;
}

function translateExact(language, text) {
  const dictionary = TRANSLATIONS[language];
  if (!dictionary) return text;
  const leading = text.match(/^\s*/)?.[0] || "";
  const trailing = text.match(/\s*$/)?.[0] || "";
  const trimmed = text.trim();
  const translated = dictionary[trimmed];
  if (translated) return `${leading}${translated}${trailing}`;
  for (const [pattern, replacement] of PATTERNS[language] || []) {
    const match = trimmed.match(pattern);
    if (!match) continue;
    const result = typeof replacement === "function"
      ? replacement(...match.slice(1))
      : trimmed.replace(pattern, replacement);
    return `${leading}${result}${trailing}`;
  }
  return text;
}

export function translateUiText(language, value) {
  if (value == null) return value;
  const normalizedLanguage = normalizeLanguage(language);
  if (normalizedLanguage === "it" || normalizedLanguage === "en") return value;
  return translateExact(normalizedLanguage, String(value));
}

export function translateUiTree(language, root = document.body) {
  const normalizedLanguage = normalizeLanguage(language);
  if (normalizedLanguage !== DEFAULT_LANGUAGE || !root) return;

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);
  for (const node of textNodes) {
    const translated = translateUiText(normalizedLanguage, node.nodeValue);
    if (translated !== node.nodeValue) node.nodeValue = translated;
  }

  const attributes = ["aria-label", "title", "placeholder"];
  root.querySelectorAll?.("*").forEach((element) => {
    for (const attribute of attributes) {
      const value = element.getAttribute(attribute);
      if (!value) continue;
      const translated = translateUiText(normalizedLanguage, value);
      if (translated !== value) element.setAttribute(attribute, translated);
    }
  });
}

export function setupUiTranslations(language) {
  const normalizedLanguage = normalizeLanguage(language);
  if (normalizedLanguage !== DEFAULT_LANGUAGE) return () => {};
  let rafId = null;
  const apply = () => {
    rafId = null;
    translateUiTree(normalizedLanguage);
  };
  const schedule = () => {
    if (rafId != null) return;
    rafId = requestAnimationFrame(apply);
  };
  schedule();
  const observer = new MutationObserver(schedule);
  observer.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ["aria-label", "title", "placeholder"],
  });
  return () => {
    if (rafId != null) cancelAnimationFrame(rafId);
    observer.disconnect();
  };
}
